// --- Global notification pub/sub (cho phép gọi showError/showSuccess từ bất kỳ đâu) ---
const __globalErrorHandlers = new Set();
const __globalSuccessHandlers = new Set();

export function showError(msg) {
  __globalErrorHandlers.forEach(h => {
    try { h(msg); } catch (e) { console.error("global error handler failed", e); }
  });
}
export function showSuccess(msg) {
  __globalSuccessHandlers.forEach(h => {
    try { h(msg); } catch (e) { console.error("global success handler failed", e); }
  });
}

function registerGlobalErrorHandler(fn) {
  __globalErrorHandlers.add(fn);
  return () => __globalErrorHandlers.delete(fn);
}
function registerGlobalSuccessHandler(fn) {
  __globalSuccessHandlers.add(fn);
  return () => __globalSuccessHandlers.delete(fn);
}

function formatDobSafe(v) {
  if (!v) return "";

  // Firestore Timestamp
  if (v?.toDate) v = v.toDate();

  // Date object
  if (v instanceof Date && !isNaN(v)) {
    const d = v.getDate(), m = v.getMonth() + 1, y = v.getFullYear();
    return `${String(d).padStart(2,"0")}/${String(m).padStart(2,"0")}/${y}`;
  }

  // Excel serial number (ngày kiểu số của Excel)
  if (typeof v === "number") {
    const ms = Math.round((v - 25569) * 86400 * 1000);
    const d = new Date(ms);
    if (!isNaN(d)) {
      return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}/${d.getFullYear()}`;
    }
  }

  // Chuỗi dd/MM, dd-MM, có/không có năm
  const s = String(v).trim();
  const m = /^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/.exec(s);
  if (m) {
    let [, dd, mm, yyyy] = m;
    if (!yyyy) {
      // không có năm → giữ nguyên dd/MM
      return `${dd.padStart(2,"0")}/${mm.padStart(2,"0")}`;
    }
    if (yyyy.length === 2) yyyy = "20" + yyyy; // 24 → 2024
    return `${dd.padStart(2,"0")}/${mm.padStart(2,"0")}/${yyyy}`;
  }

  // Không nhận dạng được → trả nguyên
  return s;
}


// ---------- Date helpers ----------
function parseDateStrToJS(value) {
  if (value == null || value === "") return null;
  if (value?.toDate) return value.toDate();
  if (value instanceof Date && !isNaN(value)) return value;

  const s = String(value).trim();

  // Excel serial number
  if (/^\d+(\.\d+)?$/.test(s)) {
    const excelSerial = Number(s);
    const js = new Date(Math.round((excelSerial - 25569) * 86400 * 1000));
    return isNaN(js) ? null : js;
  }

  // dd/MM[/yyyy] or dd-MM[-yyyy]
  const m = /^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/.exec(s);
  if (m) {
    const dd = parseInt(m[1], 10);
    const mm = parseInt(m[2], 10);
    const yy = m[3] ? parseInt(m[3], 10) : null;
    if (yy !== null) {
      const yyyy = yy < 100 ? 2000 + yy : yy;
      return new Date(yyyy, mm - 1, dd);
    }
    return null; // không có năm thì để null
  }

  const d = new Date(s);
  return isNaN(d) ? null : d;
}

function toExcelUTCDate(d) {
  if (!(d instanceof Date) || isNaN(d)) return null;
  return new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
}

function formatDobString(value) {
  if (!value) return "";
  if (value?.toDate) value = value.toDate();
  if (value instanceof Date && !isNaN(value)) {
    const d = value;
    return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}/${d.getFullYear()}`;
  }
  const s = String(value).trim();
  const m = /^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/.exec(s);
  if (m) {
    const dd = m[1].padStart(2,"0"), mm = m[2].padStart(2,"0");
    if (m[3]) {
      const yyyy = m[3].length === 2 ? "20" + m[3] : m[3];
      return `${dd}/${mm}/${yyyy}`;
    }
    return `${dd}/${mm}`;
  }
  return s;
}

// ===== Date Helpers =====
function formatDisplayDob(v) {
  if (!v) return "";

  // Firestore Timestamp
  if (v?.toDate) v = v.toDate();

  // Date object
  if (v instanceof Date && !isNaN(v)) {
    const dd = String(v.getDate()).padStart(2,"0");
    const mm = String(v.getMonth()+1).padStart(2,"0");
    const yyyy = v.getFullYear();
    return `${dd}/${mm}/${yyyy}`;
  }

  const s = String(v).trim();

  // yyyy-MM-dd
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
    const [yyyy, mm, dd] = s.split("-");
    return `${dd}/${mm}/${yyyy}`;
  }

  // dd/MM/yyyy
  const m = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/.exec(s);
  if (m) {
    let [ , dd, mm, yyyy ] = m;
    if (yyyy.length === 2) yyyy = "20"+yyyy;
    return `${dd.padStart(2,"0")}/${mm.padStart(2,"0")}/${yyyy}`;
  }

  return s;
}

// --- Helpers để hiển thị/convert giữa "dd/MM/yyyy" <-> input type="date" "yyyy-MM-dd" ---
function toInputDateValue(value) {
  // Trả về chuỗi "yyyy-MM-dd" hoặc "" nếu không có ngày hợp lệ
  if (!value) return "";
  if (value?.toDate) value = value.toDate();
  if (value instanceof Date && !isNaN(value)) {
    const yyyy = value.getFullYear();
    const mm = String(value.getMonth() + 1).padStart(2, "0");
    const dd = String(value.getDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  }
  const s = String(value).trim();
  // Nếu đang là dd/MM/yyyy hoặc dd-MM-yyyy
  const m = /^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/.exec(s);
  if (m) {
    let [ , dd, mm, yyyy ] = m;
    if (yyyy.length === 2) yyyy = "20" + yyyy;
    return `${yyyy}-${mm.padStart(2,"0")}-${dd.padStart(2,"0")}`;
  }
  // Nếu là chuỗi ISO rồi (yyyy-mm-dd), giữ nguyên nếu hợp lệ
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  return "";
}

function fromInputDateValue(inputVal) {
  // inputVal: "yyyy-MM-dd" -> trả dd/MM/yyyy
  if (!inputVal) return "";
  const parts = String(inputVal).split("-");
  if (parts.length !== 3) return "";
  const [yyyy, mm, dd] = parts;
  return `${dd.padStart(2,"0")}/${mm.padStart(2,"0")}/${yyyy}`;
}



