// ---------- CSV helpers ----------
const CSV_HEADER = [
  "Mã SV",
  "Họ",
  "Tên",
  "Ngày sinh",
  "Lớp",
  "Khoa",
  "Vai trò",
  "SĐT",
  "Khóa",
  "Trạng thái",
];


/** @param {string} csv */
function parseCSV(csv) {
  const lines = csv.split(/\r?\n/).filter(Boolean);
  if (lines.length === 0) return [];
  const header = lines[0].split(",").map((s) => s.trim());
  const idx = (k) => header.indexOf(k);
  const out = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(",").map((s) => s.trim());
    const m = {
        id: Date.now() + i,
        mssv: cols[idx("Mã SV")] || "",
        họ: cols[idx("Họ")] || "",
        name: cols[idx("Tên")] || "",
        dob: formatDobSafe(cols[idx("Ngày sinh")] || ""),
        class: cols[idx("Lớp")] || "",
        faculty: cols[idx("Khoa")] || "",
        role: cols[idx("Vai trò")] || "Thành viên",
        phone: cols[idx("SĐT")] || "",
        year: Number(cols[idx("Khóa")] || 0) || undefined,
        status: cols[idx("Trạng thái")] || "Hoạt động",
    };
    if (!m.name || !m.mssv) continue;
    out.push(m);
  }
  return out;
}

// ✅ Hàm chuẩn cho HOẠT ĐỘNG HỖ TRỢ
// Trả về: academicYear (số, ví dụ 2025), academicYearLabel ("2025-2026"), semester ("1" | "2")
function deriveAcademicForSupport(dateInput) {
  const d = dateInput && dateInput.toDate ? dateInput.toDate() : new Date(dateInput);
  const m = d.getMonth() + 1; // 1..12
  const y = d.getFullYear();

  let academicYear;
  let semester;

  if (m >= 9 && m <= 12) {
    // 9-12: kỳ 1 của năm học bắt đầu từ năm hiện tại
    academicYear = y;
    semester = "1";
  } else if (m >= 1 && m <= 5) {
    // 1-5: kỳ 2 của năm học bắt đầu từ năm trước
    academicYear = y - 1;
    semester = "2";
  } else {
    // 6-8: kỳ 1 của năm học bắt đầu từ năm hiện tại
    academicYear = y;
    semester = "1";
  }

  return { academicYear, academicYearLabel: `${academicYear}-${academicYear + 1}`, semester };
}



function deriveAcademicFromDate(dateStr) {
  const d = new Date(dateStr);
  const m = d.getMonth() + 1; // 1..12
  const y = d.getFullYear();

  // Trả về: academicYear (start-year, ví dụ 2024) và semester ("1" | "2")
  if (m >= 9)            return { academicYear: y,     semester: "1" };       // 9-12: K1 y–(y+1)
  if (m === 1)           return { academicYear: y - 1, semester: "1" };       // 1:    K1 (y-1)–y
  if (m >= 2 && m <= 6)  return { academicYear: y - 1, semester: "2" };       // 2-6:  K2 (y-1)–y
  /* m === 7 || m === 8 */ return { academicYear: y,     semester: "1" };     // 7-8:  K1 y–(y+1)
}
function getSemesterFromDate(dateStr, academicYearStart) {
  const d = new Date(dateStr);
  const m = d.getMonth(); // 0–11
  const y = d.getFullYear();

  // Kỳ 1: 9–12/N và 1/N+1
  if ((y === academicYearStart && m >= 8) || (y === academicYearStart + 1 && m === 0)) {
    return "1";
  }
  // Kỳ 2: 2–6/N+1
  if (y === academicYearStart + 1 && m >= 1 && m <= 5) {
    return "2";
  }
  return null;
}
