/** @param {Member[]} rows */
function toCSV(rows) {
  const head = CSV_HEADER.join(",");
  const body = rows
    .map((r) =>
        [r.mssv, r.họ, r.name, r.dob || "", r.class, r.faculty, r.role, r.phone || "", r.year ?? "", r.status]
          .map((v) => (v ?? "").toString().replaceAll(",", " "))
          .join(",")
      )
    .join("\n");
  return head + "\n" + body;
}

