// === Hàm xuất Excel đúng layout mẫu
function buildMonthlySheet(workbook, { stats, activities, year, month, sheetName }){
  // month: 0-11
  // const workbook = new ExcelJS.Workbook();
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  // --- Thu thập ngày có VHHĐ để chèn cột VHHĐ đúng chỗ (giống file mẫu)
  const vhhdDaysSet = new Set(
    (activities || [])
      .filter(a => (a.type === "VHHĐ") && new Date(a.date).getMonth() === month && new Date(a.date).getFullYear() === year)
      .map(a => new Date(a.date).getDate())
  );

  // === Tạo sheet theo tên mẫu
  const ws = workbook.addWorksheet(`${sheetName} tháng ${month+1} - ${year}`);

  // --- Style presets
  const borderThin = { top:{style:"thin"}, left:{style:"thin"}, right:{style:"thin"}, bottom:{style:"thin"} };
  const fillYellow = { type:"pattern", pattern:"solid", fgColor:{argb:"FFFFFF00"} };
  const fillRed = { type:"pattern", pattern:"solid", fgColor:{argb:"FFFF0000"} };
  const fillOrange = { type:"pattern", pattern:"solid", fgColor:{argb:"FFFCE5CD"} };
  const center = { horizontal:"center", vertical:"center", wrapText:true };

  // --- Kích thước hàng giống mẫu
  ws.getRow(1).height = 22;
  [2,3,4,5,6,7].forEach(r => ws.getRow(r).height = 16.5);

  // === Top legend + tiêu đề
  ws.getCell(1,1).value = "S";  ws.getCell(1,2).value = "Trực cửa sáng";
  ws.getCell(2,1).value = "C";  ws.getCell(2,2).value = "Trực cửa chiều";
  ws.getCell(3,1).value = "V";  ws.getCell(3,2).value = "VHHD";
  [ [1,1],[1,2],[2,1],[2,2],[3,1],[3,2] ].forEach(([r,c])=>{
    const cell = ws.getCell(r,c); cell.fill = fillRed; cell.font = { bold:true }; cell.alignment = center; cell.border = borderThin;
  });

  ws.getCell(1,3).value = "P"; ws.getCell(1,4).value = "Vắng CP";
  ws.getCell(2,3).value = "K"; ws.getCell(2,4).value = "Vắng KP";
  [ [1,3],[1,4],[2,3],[2,4] ].forEach(([r,c])=>{
    const cell = ws.getCell(r,c); cell.fill = fillOrange; cell.font = { bold:true }; cell.alignment = center; cell.border = borderThin;
  });

  // Tính tổng số cột: 5 cột thông tin + (mỗi ngày 2 cột S/C + cột VHHĐ tùy ngày) + 2 (TỔNG, XẾP HẠNG) + 5 (S,C,V,P,K)
  const baseCols = 5; // A..E
  // Lập sơ đồ cột cho từng ngày
  const colMap = []; // [{day, colS, colC, colVhhd?}]
  let nextCol = baseCols + 1; // bắt đầu từ cột F
  for (let d = 1; d <= daysInMonth; d++) {
    const colS = nextCol;
const colC = nextCol + 1;
let colVhhd = undefined;
let mergeEndCol = colC; // mặc định chỉ S và C

// Cột VHHĐ chèn ngay sau ngày nếu có hoạt động VHHĐ trong ngày đó
if (vhhdDaysSet.has(d)) {
  colVhhd = colC + 1;
  ws.getCell(6, colVhhd).value = "VHHĐ";
  const c = ws.getCell(6, colVhhd);
  c.fill = fillYellow; c.font = { bold:true }; c.alignment = center; c.border = borderThin;

  mergeEndCol = colVhhd; // gộp ngày/thứ tới cột VHHĐ
  nextCol = colVhhd + 1;
} else {
  nextCol = colC + 1;
}

// Dòng 4: ngày (merge S, C, và VHHĐ nếu có)
ws.mergeCells(4, colS, 4, mergeEndCol);
const dateCell = ws.getCell(4, colS);
dateCell.value = new Date(Date.UTC(year, month, d));
dateCell.numFmt = "dd/mm/yyyy";
dateCell.fill = fillYellow; dateCell.font = { bold:true }; dateCell.alignment = center; dateCell.border = borderThin;

// Dòng 5: thứ (merge S, C, và VHHĐ nếu có)
ws.mergeCells(5, colS, 5, mergeEndCol);
const weekdayCell = ws.getCell(5, colS);
weekdayCell.value = VI_WEEKDAY[new Date(year, month, d).getDay()];
weekdayCell.fill = fillYellow; weekdayCell.font = { bold:true }; weekdayCell.alignment = center; weekdayCell.border = borderThin;

// Dòng 6: header S/C
ws.getCell(6, colS).value = "S";
ws.getCell(6, colC).value = "C";
[ws.getCell(6,colS), ws.getCell(6,colC)].forEach(cell=>{
  cell.fill = fillYellow; cell.font = { bold:true }; cell.alignment = center; cell.border = borderThin;
});

colMap.push({ day: d, colS, colC, colVhhd });

  }

  // Merge & tiêu đề lớn (hàng 1) từ F1 đến cột cuối cùng
  const totalStartCol = nextCol;                 // cột cho "TỔNG"
  const rankCol      = totalStartCol + 1;        // "XẾP HẠNG"
  const sumSCol      = rankCol + 1;              // tổng S
  const sumCCol      = rankCol + 2;              // tổng C
  const sumVCol      = rankCol + 3;              // tổng V
  const sumPCol      = rankCol + 4;              // tổng P
  const sumKCol      = rankCol + 5;              // tổng K
  const lastCol      = sumKCol;



let hocKy = "";
let namHoc = "";

// Logic kỳ và năm học
if (month >= 9 && month <= 12) {
  hocKy = "I";
  namHoc = `${year}-${year + 1}`;
} else if (month === 1) {
  hocKy = "I";
  namHoc = `${year - 1}-${year}`;
} else if (month >= 2 && month <= 6) {
  hocKy = "II";
  namHoc = `${year - 1}-${year}`;
} else {
  hocKy = "";
  namHoc = "";
}

// Gộp ô tiêu đề
ws.mergeCells(1, 6, 1, lastCol);
const title = ws.getCell(1, 6);

// Tạo giá trị tiêu đề
if (hocKy && namHoc) {
  title.value = `BẢNG THEO DÕI HOẠT ĐỘNG TV CLB VHHĐ CƠ SỞ NINH BÌNH KÌ ${hocKy} NĂM HỌC ${namHoc}`;
} else {
  title.value = "BẢNG THEO DÕI HOẠT ĐỘNG TV CLB VHHĐ CƠ SỞ NINH BÌNH";
}

// Font và căn giữa
title.font = { size: 16, bold: true };
title.alignment = { vertical: "middle", horizontal: "center" };


  // Hàng 3: THÁNG / NĂM (màu vàng, merge 2-ô cặp)
  ws.mergeCells(3,6,3,7); ws.getCell(3,6).value = "Tháng";
  ws.mergeCells(3,8,3,9); ws.getCell(3,8).value = month + 1;
  ws.mergeCells(3,10,3,11); ws.getCell(3,10).value = "Năm";
  ws.mergeCells(3,12,3,13); ws.getCell(3,12).value = year;
  [6,8,10,12].forEach(c=>{
    const cell = ws.getCell(3,c);
    cell.fill = fillYellow; cell.font = { bold:true }; cell.alignment = center; cell.border = borderThin;
  });

  // === Cột thông tin đầu (A..E) + header hàng 6
  const infoHeaders = ["Mã sinh viên","Họ","Tên","Đơn vị/ Lớp","Cơ sở"];
  infoHeaders.forEach((h, i) => {
    ws.getCell(6, i+1).value = h;
    const cell = ws.getCell(6, i+1);
    cell.fill = fillYellow; cell.font = { bold:true }; cell.alignment = center; cell.border = borderThin;
  });

// === Khối TỔNG / XẾP HẠNG / (S C V P K)

// === TỔNG và XẾP HẠNG (merge 3 hàng) ===
ws.mergeCells(4, totalStartCol, 6, totalStartCol);
const cellTotal = ws.getCell(4, totalStartCol);
cellTotal.value = "TỔNG";
cellTotal.alignment = { horizontal: "center", vertical: "middle", wrapText: true };
cellTotal.fill = fillYellow;
cellTotal.font = { bold: true };
cellTotal.border = borderThin;

ws.mergeCells(4, rankCol, 6, rankCol);
const cellRank = ws.getCell(4, rankCol);
cellRank.value = "XẾP HẠNG";
cellRank.alignment = { horizontal: "center", vertical: "middle", wrapText: true };
cellRank.fill = fillYellow;
cellRank.font = { bold: true };
cellRank.border = borderThin;

// === Trực cửa sáng, Trực cửa chiều, VHHD, Vắng CP, Vắng KP (merge 4-5) ===
[sumSCol, sumCCol, sumVCol, sumPCol, sumKCol].forEach((c, i) => {
  ws.mergeCells(4, c, 5, c);
  const headerCell = ws.getCell(4, c); // chỉ style ô gốc
  headerCell.value = ["Trực cửa sáng","Trực cửa chiều","VHHD","Vắng CP","Vắng KP"][i];
  headerCell.alignment = { horizontal: "center", vertical: "middle", wrapText: true };
  headerCell.fill = fillYellow;
  headerCell.font = { bold: true };
  headerCell.border = borderThin;

  // Hàng 6: ký hiệu
  const subCell = ws.getCell(6, c);
  subCell.value = ["S","C","V","P","K"][i];
  subCell.alignment = { horizontal: "center", vertical: "middle" };
  subCell.fill = fillYellow;
  subCell.font = { bold: true };
  subCell.border = borderThin;
});


// Căn giữa tất cả các ô trong bảng (trừ cột TỔNG và XẾP HẠNG)
ws.eachRow({ includeEmpty: true }, (row, rowNumber) => {
  row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
    // Bỏ qua cột TỔNG và XẾP HẠNG
    if (colNumber === totalStartCol || colNumber === rankCol) {
      return;
    }

    cell.alignment = { horizontal: "center", vertical: "middle", wrapText: true };
  });
});

ws.views = [
  { state: 'frozen', xSplit: 5, ySplit: 0 } // xSplit=5 => ghim 5 cột (A..E)
];


  // === Ghi dữ liệu
  // Độ rộng cột — gần giống mẫu
  const setW = (col, w) => (ws.getColumn(col).width = w);
  [ [1,12.6],[2,21.9],[3,12.6],[4,14.5],[5,12.6] ].forEach(([c,w])=>setW(c,w));
  for (const {colS, colC, colVhhd} of colMap) {
    setW(colS, 13); setW(colC, 13);
    if (colVhhd) setW(colVhhd, 10.5);
  }
  [ [totalStartCol,10.5],[rankCol,10.5],[sumSCol,9],[sumCCol,9],[sumVCol,9],[sumPCol,9],[sumKCol,9] ]
    .forEach(([c,w])=>setW(c,w));

  const isSameDay = (d1, d2) => (
    d1.getFullYear()===d2.getFullYear() &&
    d1.getMonth()===d2.getMonth() &&
    d1.getDate()===d2.getDate()
  );

  const startDataRow = 7;
  (stats || []).forEach((m, idx) => {
    const r = startDataRow + idx;

    const MSSV = m.mssv ?? m.MSSV ?? m.code ?? "";
    const lastName = m["họ"] ?? m.ho ?? m.lastName ?? "";
    const firstName = m.name ?? m.ten ?? m.firstName ?? "";
    const lop = m.class ?? m.lop ?? m["Đơn vị/ Lớp"] ?? "";
    const coso = m.faculty ?? m.coso ?? "Nam Định";

    ws.getCell(r,1).value = MSSV;
    ws.getCell(r,2).value = lastName;
    ws.getCell(r,3).value = firstName;
    ws.getCell(r,4).value = lop;
    ws.getCell(r,5).value = coso;

    // Đếm tổng
    let sumS = 0, sumC = 0, sumV = 0, sumP = 0, sumK = 0;

    for (const map of colMap) {
      const d = new Date(year, month, map.day);
      const acts = (activities || []).filter(a => String(a.memberId) === String(m.id || m.memberId || MSSV))
                                     .filter(a => isSameDay(new Date(a.date), d));

      // Morning (S)
      const hasS = acts.some(a => a.type === "Trực cửa sáng");
      const absentS_P = acts.some(a => a.type === "Vắng CP" && a.subType === "S");
      const absentS_K = acts.some(a => a.type === "Vắng KP" && a.subType === "S");
      let vS = "";
      if (hasS) { vS = "S"; sumS++; }
      else if (absentS_P) { vS = "P"; sumP++; }
      else if (absentS_K) { vS = "K"; sumK++; }
      ws.getCell(r, map.colS).value = vS;

      // Afternoon (C)
      const hasC = acts.some(a => a.type === "Trực cửa chiều");
      const absentC_P = acts.some(a => a.type === "Vắng CP" && a.subType === "C");
      const absentC_K = acts.some(a => a.type === "Vắng KP" && a.subType === "C");
      let vC = "";
      if (hasC) { vC = "C"; sumC++; }
      else if (absentC_P) { vC = "P"; sumP++; }
      else if (absentC_K) { vC = "K"; sumK++; }
      ws.getCell(r, map.colC).value = vC;

      // VHHĐ (nếu có cột)
      if (map.colVhhd) {
        const hasV = acts.some(a => a.type === "VHHĐ");
        ws.getCell(r, map.colVhhd).value = hasV ? "V" : "";
        if (hasV) sumV++;
      } else {
        // Không có cột VHHĐ cho ngày này, vẫn cộng tổng nếu có
        if (acts.some(a => a.type === "VHHĐ")) sumV++;
      }
    }

    // Tổng = S + C (giống mẫu)
    ws.getCell(r, totalStartCol).value = (m.total ?? (sumS + sumC));
    ws.getCell(r, rankCol).value = (m.rank ?? "");

    // Block S C V P K
    ws.getCell(r, sumSCol).value = (m.morning ?? sumS);
    ws.getCell(r, sumCCol).value = (m.afternoon ?? sumC);
    ws.getCell(r, sumVCol).value = (m.vhhd ?? sumV);
    ws.getCell(r, sumPCol).value = (m.vangCP ?? sumP);
    ws.getCell(r, sumKCol).value = (m.vangKP ?? sumK);
  });

  // === Viền & căn giữa toàn vùng bảng từ hàng 4 đến hết dữ liệu
  const lastRow = startDataRow + (stats?.length || 0) - 1;
  for (let r = 4; r <= Math.max(6, lastRow); r++) {
  for (let c = 1; c <= lastCol; c++) {
    const cell = ws.getCell(r,c);
    cell.border = borderThin;
    // chỉ set alignment nếu ô chưa có
    if (!cell.alignment) {
      cell.alignment = center;
    }
  }
}


  // Làm nổi bật cột XẾP HẠNG (nền đỏ, chữ trắng) & TỔNG (in đậm)
  for (let r = startDataRow; r <= lastRow; r++) {
    const totalCell = ws.getCell(r, totalStartCol);
    totalCell.font = { bold:true };
    const rankCell = ws.getCell(r, rankCol);
    rankCell.fill = fillRed; rankCell.font = { bold:true, color:{argb:"FFFFFFFF"} };
  }

  // Xuất file
  // const buf = await workbook.xlsx.writeBuffer();
  //saveAs(new Blob([buf]), `TheoDoiTruc_${month+1}_${year}.xlsx`);
}

async function exportSupportSemesterExcel({ supports, semester, academicYear, members }) {
  try {
    console.log("[exportSupportSemesterExcel] inputs:", {
      supportsLength: supports?.length ?? 0,
      semester, academicYear, membersLength: members?.length ?? 0
    });

    if (!semester || semester === "all") { showError("Vui lòng chọn Kỳ."); return; }

    // lọc hoạt động trong kỳ
    const list = (supports || []).filter(s =>
      String(s.semester) === String(semester) &&
      Number(s.academicYear) === Number(academicYear)
    );
    if (list.length === 0) { showError("Chưa có hoạt động trong kỳ đã chọn!"); return; }

    const workbook = new ExcelJS.Workbook();
    const borderThin = { top:{style:"thin"}, left:{style:"thin"}, right:{style:"thin"}, bottom:{style:"thin"} };
    const center = { horizontal:"center", vertical:"middle", wrapText:true };
    const headerFill = { type:"pattern", pattern:"solid", fgColor:{argb:"FFFFEB3B"} };
    const fmtDate = (v) => formatDobString(v);
    const sheetSafe = (name) => (name || "").replace(/[\\/*?:\[\]]/g, " ").slice(0,31).trim() || "Sheet";

    // lấy attendees của từng hoạt động
    const attendeesBySupport = {};
    for (const s of list) {
      try {
        const snap = await getDocs(collection(db, "supportActivities", s.id, "attendees"));
        attendeesBySupport[s.id] = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      } catch (err) {
        console.error(`[exportSupportSemesterExcel] Lỗi getDocs cho support ${s.id}:`, err);
        attendeesBySupport[s.id] = [];
      }
    }

    // gom tất cả sinh viên
    const allStudents = new Map();
    for (const s of list) {
      for (const a of (attendeesBySupport[s.id] || [])) {
        const mssv = a.mssv || a.MSSV || "";
        if (!mssv) continue;
        const m = (members || []).find(x => x.mssv === mssv) || {};
        allStudents.set(mssv, {
          mssv,
          họ: a.họ ?? m.họ ?? "",
          name: a.name ?? m.name ?? "",
          dob: a.dob ?? m.dob ?? "",
          class: a.class ?? m.class ?? "",
          faculty: a.faculty ?? m.faculty ?? "",
        });
      }
    }
    if (allStudents.size === 0) { showError("Chưa có người tham gia nào trong kỳ đã chọn!"); return; }

    // định nghĩa cột
   const colDefs = list
  .map(s => {
    const d = s.date?.toDate ? s.date.toDate() : new Date(s.date);
    const dd = isNaN(d) ? "" : `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}`;
    return { 
      id: s.id, 
      title: `HT ${String(s.name || "").toUpperCase()} NGÀY ${dd}`.trim(), 
      date: d   // thêm dòng này để sort hoạt động
    };
  })
  .sort((a, b) => a.date - b.date);  // giờ sort mới có tác dụng


    // ---------------- SHEET TỔNG ----------------
    const wsSum = workbook.addWorksheet("DS TỔNG HỢP");
    const roman = semester === "1" ? "I" : "II";
    wsSum.mergeCells(1,1,1,7 + colDefs.length + 1);
    wsSum.getCell(1,1).value = `DANH SÁCH TV THAM GIA HỖ TRỢ HOẠT ĐỘNG - KỲ ${roman} NĂM HỌC ${academicYear}-${academicYear+1}`;
    wsSum.getCell(1,1).font = { bold:true, size:16 };
    wsSum.getCell(1,1).alignment = center;

    const headers = ["STT","Mã SV","Họ","Tên","Ngày sinh","Lớp","Khoa","Cơ sở", ...colDefs.map(c=>c.title), "Tổng"];
    wsSum.addRow([]);
    const hr = wsSum.addRow(headers);
    hr.eachCell(c=>{ c.border=borderThin; c.fill=headerFill; c.alignment=center; c.font={bold:true}; });

    const studentsSorted = Array.from(allStudents.values());
    studentsSorted.forEach((st, idx) => {
      const marks = colDefs.map(c => (attendeesBySupport[c.id]||[]).some(a=>a.mssv===st.mssv) ? "X" : "");
      const total = marks.filter(x=>x==="X").length;
      wsSum.addRow([
        idx+1, st.mssv, st.họ, st.name, fmtDate(st.dob), st.class, st.faculty, "Ninh Bình",
        ...marks,
        total
      ]);
    });
    wsSum.eachRow((r,i)=> i>=2 && r.eachCell(c=>{c.border=borderThin;c.alignment=center;}));
    wsSum.views = [{ state: "frozen", ySplit: 2, xSplit: 8 }];

    // ---------------- SHEET TỪNG HOẠT ĐỘNG ----------------
    const usedSheetNames = new Set();
    for (const s of list) {
      let baseName = `HT ${s.name || ""}`;
      const d = s.date?.toDate ? s.date.toDate() : new Date(s.date);
      if (!isNaN(d)) {
        const dd = String(d.getDate()).padStart(2,"0");
        const mm = String(d.getMonth()+1).padStart(2,"0");
        baseName += ` ${dd}-${mm}`;
      }
      let safeName = sheetSafe(baseName);
      let counter = 1;
      while (usedSheetNames.has(safeName)) {
        safeName = sheetSafe(`${baseName}_${counter++}`);
      }
      usedSheetNames.add(safeName);

      const ws = workbook.addWorksheet(safeName);
      ws.mergeCells(1,1,1,7);
      ws.getCell(1,1).value = `DANH SÁCH THAM GIA: ${s.name} (${fmtDate(s.date)})`;
      ws.getCell(1,1).font = {bold:true,size:14};
      ws.getCell(1,1).alignment=center;

      const head=["STT","Mã SV","Họ","Tên","Ngày sinh","Lớp","Khoa"];
      const hr=ws.addRow(head);
      hr.eachCell(c=>{c.border=borderThin;c.fill=headerFill;c.alignment=center;c.font={bold:true};});

      (attendeesBySupport[s.id]||[]).forEach((a,i)=>{
        ws.addRow([i+1,a.mssv,a.họ,a.name,fmtDate(a.dob),a.class,a.faculty]);
      });
      ws.eachRow((r,i)=> i>=2 && r.eachCell(c=>{c.border=borderThin;c.alignment=center;}));
      // chỉnh độ rộng cột theo dữ liệu
      ws.columns = [
        { key: "stt", width: 5 },
        { key: "mssv", width: 15 },
        { key: "ho", width: 20 },
        { key: "ten", width: 12 },
        { key: "dob", width: 12 },
        { key: "class", width: 18 },
        { key: "faculty", width: 30 }
      ];

      ws.views = [{ state: "frozen", ySplit: 2 }];

    }

    // ---------------- Xuất file ----------------
    const buf=await workbook.xlsx.writeBuffer();
    saveAs(new Blob([buf]), `HoTro_Ky${semester}_${academicYear}-${academicYear+1}.xlsx`);
    console.log("[exportSupportSemesterExcel] Xuất thành công");
  } catch(e) {
    console.error("[exportSupportSemesterExcel] Tổng lỗi:", e);
    showError("Xuất Excel thất bại! Xem console để biết chi tiết.");
  }
}

