// Thay thế toàn bộ hàm exportExcelFromFirestore cũ bằng hàm này
async function exportExcelFromFirestore() {
  try {
    const querySnapshot = await getDocs(collection(db, "members"));
    const list = querySnapshot.docs.map(d => ({ id: d.id, ...d.data() }));

    if (!list || list.length === 0) {
      showError("Không có dữ liệu thành viên!");
      return;
    }

    const workbook = new ExcelJS.Workbook();
    const ws = workbook.addWorksheet("Thành viên");

    const borderThin = { top:{style:"thin"}, left:{style:"thin"}, right:{style:"thin"}, bottom:{style:"thin"} };
    const center = { horizontal:"center", vertical:"middle", wrapText:true };

    // --- Tiêu đề lớn (hàng 1, merge) ---
    ws.mergeCells(1,1,1,11);
    ws.getCell(1,1).value = "DANH SÁCH THÀNH VIÊN CÂU LẠC BỘ";
    ws.getCell(1,1).font = { bold:true, size:14 };
    ws.getCell(1,1).alignment = center;

    // --- Header (hàng 2) ---
    const headers = ["STT","Mã SV","Họ","Tên","Ngày sinh","Lớp","Khoa","Vai trò","SĐT","Khóa","Trạng thái"];
    // thêm 1 dòng trống (nếu muốn khoảng cách)
    ws.addRow([]);
    const hr = ws.addRow(headers);
    hr.eachCell(cell => {
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFFFEB3B" } }; // vàng nhạt
      cell.font = { bold: true };
      cell.alignment = center;
      cell.border = borderThin;
    });

    // --- Helper format date (hàm nội bộ để an toàn với Firestore Timestamp) ---
    const parseDateOrString = (v) => {
      if (!v) return "";
      try {
        const d = v?.toDate ? v.toDate() : new Date(v);
        if (isNaN(d)) return String(v);
        return d;
      } catch (e) {
        return String(v);
      }
    };

    // --- Dữ liệu ---
    list.forEach((r, idx) => {
  const jsDob = parseDateStrToJS(r.dob);

  let dobCellVal;
  if (jsDob) {
    // Có năm => lưu dạng Date UTC để Excel hiển thị đúng
    dobCellVal = toExcelUTCDate(jsDob);
  } else {
    // Không có năm => lưu text, thêm ' để Excel không đảo dd/MM
    const txt = formatDobString(r.dob);
    dobCellVal = txt ? "'" + txt : "";
  }

  ws.addRow([
    idx + 1,
    r.mssv || "",
    r.họ || "",
    r.name || "",
    dobCellVal,
    r.class || "",
    r.faculty || "",
    r.role || "",
    r.phone || "",
    (r.year ?? "") || "",
    r.status || ""
  ]);
});


    // --- Định dạng cột & rộng cột ---
    // cột 5 là "Ngày sinh" -> set numFmt nếu là Date
    ws.getColumn(5).numFmt = "dd/mm/yyyy";

    const colWidths = [6,15,20,14,12,14,20,16,14,10,14];
    colWidths.forEach((w, i) => ws.getColumn(i+1).width = w);

    // --- Border + alignment cho vùng dữ liệu (bắt đầu từ row 3 trở đi) ---
    ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
      if (rowNumber <= 2) return; // bỏ qua title + header
      row.eachCell(cell => {
        cell.border = borderThin;
        if (!cell.alignment) cell.alignment = center;
      });
    });

    // --- Freeze header & Auto filter ---
    ws.views = [{ state: "frozen", ySplit: 3}];
    ws.autoFilter = {
  from: { row: 3, column: 1 },
  to: { row: 3, column: headers.length }
};

    // --- (Tùy chọn) làm mờ xen kẽ hàng để dễ đọc ---
    for (let r = 3; r <= ws.rowCount; r++) {
      if ((r - 3) % 2 === 1) {
        ws.getRow(r).eachCell(c => {
          if (!c.fill) c.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFF7F7F7" } };
        });
      }
    }

    // --- Xuất file ---
    const buf = await workbook.xlsx.writeBuffer();
    saveAs(new Blob([buf]), `DS_ThanhVien_${new Date().getFullYear()}.xlsx`);
  } catch (err) {
    console.error("[exportExcelFromFirestore]", err);
    showError("Xuất Excel thất bại! Xem console để biết chi tiết.");
  }
}







function download(filename, text) {
  const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
const POINTS = {
  "Trực cửa sáng": 1,
  "Trực cửa chiều": 0.5,
  "VHHĐ": 1.5,
  "Vắng CP": -0.5,
  "Vắng KP": -1.5,
};

const calculateMonthlyStats = (members, activities, year, month) => {
  const scoreMap = { S: 1, C: 0.5, V: 1.5, P: -0.5, K: -1.5 };

  let stats = members.map(m => {


    return {
      id: m.id,
      mssv: m.mssv,
      họ: m.họ,
      name: m.name,
      class: m.class,
      total: 0,
      morning: 0,
      afternoon: 0,
      vhhd: 0,
      vangCP: 0,
      vangKP: 0,
    };
  });

  activities.forEach(act => {
    const d = new Date(act.date);
    if (d.getFullYear() === year && d.getMonth() === month) {
      const member = stats.find(s => s.id === act.memberId);
      if (member) {
        if (act.type === "Trực cửa sáng") { member.total += scoreMap.S; member.morning++; }
        if (act.type === "Trực cửa chiều") { member.total += scoreMap.C; member.afternoon++; }
        if (act.type === "VHHĐ") { member.total += scoreMap.V; member.vhhd++; }
        if (act.type === "Vắng CP") { member.total += scoreMap.P; member.vangCP++; }
        if (act.type === "Vắng KP") { member.total += scoreMap.K; member.vangKP++; }
      }
    }
  });

  stats.sort((a, b) => b.total - a.total);
  stats = stats.map((m, idx) => ({ ...m, rank: idx + 1 }));

  return stats;
};

function SupportCheckinScreen({ supportId, rows, setSupportAttendees }) {
  const [mssv, setMssv] = useState("");
  const [note, setNote] = useState("");
  const [saving, setSaving] = useState(false);
  const [locked, setLocked] = useState(false);
  const [message, setMessage] = useState(null);
  const [supportName, setSupportName] = useState("");
  const [deviceId, setDeviceId] = useState(null);
  // 🔒 2) locked toàn bộ do admin/BCN
  const [lockedByAdmin, setLockedByAdmin] = useState(false);
  // ⏰ hạn điểm danh
  const [endTime, setEndTime] = useState(null);

  const member = rows.find(r => r.mssv === mssv);

 // ✅ Lấy deviceId (tạo nếu chưa có)
useEffect(() => {
  async function getDeviceId() {
    const fp = await FingerprintJS.load();
    const result = await fp.get();
    setDeviceId(result.visitorId); // luôn cố định cho máy, không mất khi xoá cache
  }
  getDeviceId();
}, []);


  // ✅ Lấy thông tin hoạt động (tên, endTime, lockedByAdmin)
  useEffect(() => {
    async function fetchSupport() {
      const docRef = doc(db, "supportActivities", supportId);
      const snap = await getDoc(docRef);
      if (snap.exists()) {
        const data = snap.data();
        setSupportName(data.name);
        setEndTime(data.endTime ? data.endTime.toDate() : null);
        setLockedByAdmin(!!data.locked);
      }
    }
    if (supportId) fetchSupport();
  }, [supportId]);

  // ✅ Check server: device này đã điểm danh chưa?
  useEffect(() => {
    if (!deviceId) return;
    async function checkDevice() {
      // Kiểm tra deviceId đã dùng chưa
      const q = query(
        collection(db, `supportActivities/${supportId}/attendees`),
        where("deviceId", "==", deviceId)
      );
      const snap = await getDocs(q);
      if (!snap.empty) {
        // 🟢 Thiết bị đã điểm danh
        setLocked(true);
      }

    }
    checkDevice();
  }, [deviceId, supportId]);

  // ✅ Hàm xử lý điểm danh
  const handleCheckin = async () => {
    setSaving(true);
    try {
      // 0. Check bị khóa bởi admin/BCN
      if (lockedByAdmin) {
        setMessage({ type: "error", text: "🚫 Điểm danh đã bị khóa!" });
        setSaving(false);
        return;
      }
      // 0.1 Check hết hạn
      if (endTime && new Date() > endTime) {
        setMessage({ type: "error", text: "⏰ Mã đã hết thời gian điểm danh!" });
        setSaving(false);
        return;
      }
      // 1. MSSV rỗng
      if (!mssv || mssv.trim() === "") {
        setMessage({ type: "error", text: "⚠️ Vui lòng nhập Mã sinh viên trước khi điểm danh!" });
        setSaving(false);
        return;
      }

      // 2. MSSV không tồn tại trong danh sách
      if (!member) {
        setMessage({ type: "error", text: "❌ Sinh viên không tồn tại trong danh sách!" });
        setMssv("");
        setNote("");
        setTimeout(() => setMessage(null), 2000);
        setSaving(false);
        return;
      }

      // 3. MSSV đã điểm danh (check Firestore)
      const q = query(
        collection(db, `supportActivities/${supportId}/attendees`),
        where("mssv", "==", member.mssv)
      );
      const snap = await getDocs(q);
      if (!snap.empty) {
        // 🔴 MSSV đã điểm danh (trên máy này hay máy khác đều chung logic)
        setMessage({ type: "mssv-exist", text: "⚠️ Mã sinh viên này đã điểm danh rồi!" });
        setMssv("");
        setNote("");
        setTimeout(() => setMessage(null), 2000);
        setSaving(false);
        return;
      }

      // 4. Thêm điểm danh mới (có deviceId)
      const newData = {
        mssv: member.mssv,
        họ: member.họ || "",
        name: member.name || "",
        dob: member.dob || "",
        class: member.class || "",
        faculty: member.faculty || "",
        note,
        deviceId, // 🔒 quan trọng: lưu deviceId
        ts: new Date()
      };

      const docRef = await addDoc(
        collection(db, `supportActivities/${supportId}/attendees`),
        newData
      );

      if (typeof setSupportAttendees === "function") {
        setSupportAttendees(prev => [{ id: docRef.id, ...newData }, ...prev]);
      }

      setMssv("");
      setNote("");
      setLocked(true);

      setMessage({ type: "success", text: "✔️ Điểm danh thành công!" });
      setTimeout(() => setMessage(null), 2000);
    } catch (e) {
      console.error(e);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-red-50 p-4">
      <div className="bg-white p-6 rounded-3xl shadow w-full max-w-md">
        <div className="text-xl font-bold mb-2 text-center text-red-600">
          Điểm danh hỗ trợ
        </div>

        {supportName && (
          <div className="text-center text-gray-700 mb-4 font-medium">
            Hoạt động: <span className="text-red-500">{supportName}</span>
          </div>
        )}
        
        {endTime && (
          <div className="text-center text-gray-500 mb-2 text-sm">
            ⏰ Hạn điểm danh: {endTime.toLocaleString("vi-VN")}
          </div>
        )}

        {lockedByAdmin && (
          <div className="text-center text-red-600 font-medium mb-2">
            🚫 Điểm danh đã bị khóa
          </div>
        )}

        <div className="text-gray-600 text-center mb-4">
          Nhập <b>Mã sinh viên</b> của bạn để điểm danh.
        </div>

        <div className="space-y-3">
          <Input
            placeholder="Mã sinh viên"
            value={mssv}
            onChange={(e) => setMssv(e.target.value.trim())}
          />
          <Input
            placeholder="Ghi chú (nếu có)"
            value={note}
            onChange={(e) => setNote(e.target.value)}
          />

          {member && mssv && (
            <div className="text-sm text-gray-600">
              <div><b>Họ tên:</b> {member.họ} {member.name}</div>
              <div><b>Lớp:</b> {member.class} · <b>Khoa:</b> {member.faculty}</div>
            </div>
          )}

          {message && (
            <div
              className={`px-4 py-2 rounded mb-2 text-sm ${
                message.type === "success"
                  ? "bg-green-100 border border-green-400 text-green-700"
                  : message.type === "error"
                  ? "bg-red-100 border border-red-400 text-red-700"
                  : "bg-yellow-100 border border-yellow-400 text-yellow-700"
              }`}
            >
              {message.text}
            </div>
          )}

          {locked ? (
            <div className="p-3 text-center bg-green-50 border border-green-300 rounded">
              <p className="text-green-700 font-medium">✔️ Bạn đã điểm danh!</p>
              <p className="text-gray-500 text-sm mt-1">
                Bạn không thể điểm danh thêm lần nữa.
              </p>
            </div>
          ) : (
            <Button
              className="!bg-red-500 !text-white w-full hover:!bg-red-600"
              disabled={saving}
              onClick={handleCheckin}
            >
              {saving ? "Đang lưu..." : "Xác nhận điểm danh"}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}



