  function countVhhd(memberId, period = "month", academicYearStart) {
  const set = new Set();

  activities.forEach(a => {
    if (a.memberId !== memberId || a.type !== "VHHĐ") return;
    const d = new Date(a.date);

    let ok = false;
    if (period === "month") {
      ok = d.getFullYear() === selectedYear && d.getMonth() === selectedMonth;
    } 
    else if (period === "semester") {
      // nếu derivedSemester === null => nghỉ hè => không có kỳ
      if (!derivedSemester) ok = false;
      else if (derivedSemester === "1") {
        ok =
          (d.getFullYear() === derivedAcademicYear && [8,9,10,11].includes(d.getMonth())) ||
          (d.getFullYear() === derivedAcademicYear + 1 && d.getMonth() === 0);
      } else if (derivedSemester === "2") {
        ok = d.getFullYear() === derivedAcademicYear && [1,2,3,4,5].includes(d.getMonth());
      }
    } 
    else if (period === "academic") {
      // năm học: 9/N → 8/N+1 dựa trên derivedAcademicYear
      const start = new Date(derivedAcademicYear, 8, 1);   // 01/09/derivedAcademicYear
      const end   = new Date(derivedAcademicYear + 1, 7, 31, 23,59,59); // 31/08/next
      ok = d >= start && d <= end;
    }

    if (ok) {
      // chỉ tính 1 buổi / ngày
      set.add(d.toISOString().slice(0,10));
    }
  });

  return set.size;
}


 
